AND s.status IN (0, 1)AND s.status = #{status}
AND s.business_type = #{businessType}
AND (u1.nick_name LIKE CONCAT('%', #{keyword}, '%') OR u2.nick_name LIKE CONCAT('%', #{keyword}, '%') OR s.business_name LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY s.last_message_time DESC, s.created_at DESC

