SELECT COALESCE(
    SUM(CASE WHEN user1_id = #{userId} THEN user1_unread ELSE user2_unread END),
    0
)
FROM sys_chat_session
WHERE user1_id = #{userId} OR COALESCE(assigned_admin_id, user2_id) = #{userId}

